head.script:
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.haltTpCd = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.haltTpCd = (arrPar.length >= 6 ? arrPar[5] : ""); // 거래정지지정및해제구분코드
            scwin.gubun = (arrPar.length >= 7 ? arrPar[6] : ""); // 발행사/기초자산 구분값

        }

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
        }
        $c.cm.PanelToGroupBox(panel_3);
        $c.libRoundPanel.PanelToGroupBox(panel_2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05932.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh(); // 목록 다시 조회

        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Rsn_OnLoadError
 * @description dts_Rsn 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Rsn_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Rsn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.dts_Rsn_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadError
 * @description dts_Mst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.dts_Mst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no !== "") {
            $c.stf.setButtonSetWithDate(edt_TrdHaltEndDd, false);
        }

        // if (fr_bz_procs_no != "") {
        if (edt_TrdHaltEndDd.getValue() !== "") {
            $c.stf.setButtonSetWithDate(edt_TrdHaltEndDd, false);
        } else {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05932.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05932.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_SetTrdHaltStrtDd_onclick
 * @description img_SetTrdHaltStrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetTrdHaltStrtDd_onclick = function() {
    try {
        popUpCalendar2(edt_TrdHaltEndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05932.img_SetTrdHaltStrtDd_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/tradingSuspension.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/tradingSuspension.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions3 = {
            id : "sbm_dts_Rsn",
            action : "/tradingSuspension.do",
            ref : "",
            target : "dts_Rsn=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_dts_Rsn_Uly",
            action : "/tradingSuspension.do",
            ref : "",
            target : "dts_Rsn_Uly=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name saveTrs
 * @description ELW는 항상  종목별기준으로 처리함
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_210 + ",DIV_IDX[0]=" + DIV_IDX_ASGN
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/tradingSuspension.do",
        ref : "dts_Mst",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (!$c.lc.checkDdTm("DD", edt_TrdHaltEndDd, "매매거래해제", false)) return false;
    if (edt_TrdHaltStrtDd.getValue() >= edt_TrdHaltEndDd.getValue()) {
        await $c.win.alert("[거래정지 해제일]은  [거래정지 지정일]이후로 입력하세요.");
        edt_TrdHaltEndDd.focus();
        return false;
    }

    // if( ! checkEmptyValue( txb_HaltReleasRsnNm , "해제사유" ) ) return false ;
    // if( ! checkMaxLength( txb_HaltReleasRsnNm , 80 , "해제사유" ) ) return false ;

    // if( ! checkEmptyValue( txb_HaltReleasGrndRegulNm , "해제근거규정" ) ) return false ;
    // if( ! checkMaxLength( txb_HaltReleasGrndRegulNm , 200 , "해제근거규정" ) ) return false ;

    if (!$c.stf.checkMaxLength(txa_HaltReleastmRefContn, 2000, "해제기타")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('R')) return;
        scwin.trsIdx = TRS_IDX_INSERT2;
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "TRD_HALT_RELEAS_BZ_PROCS_NO", await $c.stf.getNewBzProcNo(dts_BzProcsNo));
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_DESNRELS_TP_CD", scwin.haltTpCd);
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE2;
        if (!$c.lc.fn_isProcess('U')) return;
        await scwin.saveTrs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE2;
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_DESNRELS_TP_CD", '0');
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "TRD_HALT_END_DD", '');
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_RELEAS_RSN_NM", '');
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_RELEAS_GRND_REGUL_NM", '');
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_RELEASTM_REF_CONTN", '');
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        if (scwin.gubun === '1') {
            // 발행사 기준
            arr[0] = "68954G";
        } else if (scwin.gubun === '2') {
            // 기초자산 기준
            arr[0] = "68954H";
        }
        arr[1] = dts_Mst.getCellData(dts_Mst.getRowPosition(), "TRD_HALT_RELEAS_BZ_PROCS_NO");
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        // arr[4]; //ctnt
        arr[5] = $c.lc.fn_GetAddTitle(dts_Mst.getCellData(dts_Mst.getRowPosition(), "COM_NM")); // add  title

        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        $c.stf.copyDataSet(dts_Rsn, param_dts2);
        $c.stf.copyDataSet(dts_Rsn_Uly, param_dts3);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "TGT_NM", scwin.Isur_nm);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name drft
 * @description drft 처리
