scwin.makt = function() {

};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    let fr_fn_list_sync = $c.frame.path("../").fn_parentRefresh; // 정지에서 해제로 창을 띄운경우
    if (fr_fn_list_sync === undefined) {
        fr_fn_list_sync = $c.frame.path("../").fn_search; // 바로 해제창을 띄운경우

    }
    // alert('[fr_fn_list_sync]'+fr_fn_list_sync);
    fr_fn_list_sync();
};
